+	}
+	if info.Mode().Perm()&0o077 == 0 {
+		return nil
+	}
+	if err := os.Chmod(dir, info.Mode().Perm()&^0o077); err != nil {
+		return fmt.Errorf("tighten %s: %w", dir, err)
+	}
+	return nil
