commit 7ac91dd4fbad1c1e3415479d3ab05cbaebae7e48
Author: Peyton Montei <peyton@entire.io>
Date:   Fri Aug 28 17:25:05 2026 -0700

    fix(settings): per-block strictness for the user settings file

    LoadUserSettings strict-decoded the WHOLE file, so a newer entire adding any
    top-level key would switch the tier off (fail closed) for every older binary
    sharing the machine — and an older binary's `entire trust` would then also
    drop the newer binary's blocks on write. Strictness is now per block:

    - the `global` block still rejects unknown keys (an older binary must never
      misread recorded consent it does not understand);
    - unknown top-level blocks are tolerated and round-tripped byte-for-byte
      through ModifyUserSettings.

    New features therefore add top-level blocks, not keys inside `global`.
    Documented in the type comment and docs/architecture/global-tracking.md.

    Co-Authored-By: Claude Fable 5 <noreply@anthropic.com>
    Entire-Checkpoint: 01M15EFRG6WQTPJ6ZQHWWAKPNG

diff --git a/cmd/entire/cli/settings/repopolicy/types.go b/cmd/entire/cli/settings/repopolicy/types.go
--- a/cmd/entire/cli/settings/repopolicy/types.go
+++ b/cmd/entire/cli/settings/repopolicy/types.go
@@ -2,7 +2,10 @@
 // classify repository tracking policy.
 package repopolicy

-import "path/filepath"
+import (
+	"encoding/json"
+	"path/filepath"
+)

 // ActivationSource identifies the authority that activated tracking.
 type ActivationSource string
@@ -195,8 +198,20 @@ type GlobalConfig struct {

 // UserSettings is the root of the user-global settings file. A nil Global
 // distinguishes an unconfigured tier from a configured but disabled tier.
+//
+// Strictness is per block, not per file (see UnmarshalJSON): the `global`
+// block rejects unknown keys — fail closed, so an older binary never
+// misreads recorded consent it does not understand — while unknown top-level
+// blocks are tolerated and round-tripped untouched, so a newer entire can add
+// a block without switching the tier off for every older binary that shares
+// the machine. New features therefore add top-level blocks, not keys inside
+// `global`.
 type UserSettings struct {
 	Global *GlobalConfig `json:"global,omitempty"`
+	// extra holds top-level blocks this binary does not know, preserved
+	// byte-for-byte across read-modify-write so a newer binary's settings
+	// survive an older one's `entire trust`.
+	extra map[string]json.RawMessage
 }

 // GlobalConfigured reports whether the global tier has been configured.
diff --git a/cmd/entire/cli/settings/repopolicy/user_settings.go b/cmd/entire/cli/settings/repopolicy/user_settings.go
--- a/cmd/entire/cli/settings/repopolicy/user_settings.go
+++ b/cmd/entire/cli/settings/repopolicy/user_settings.go
@@ -42,9 +42,66 @@ func resolveUserSettingsPath() (string, error) {
 	return filepath.Join(configDir, UserSettingsFileName), nil
 }

-// LoadUserSettings strictly decodes user-global settings. A missing file is
-// an unconfigured tier; malformed or unknown input returns an error so callers
-// can fail closed.
+// userSettingsGlobalKey is the one block this binary interprets.
+const userSettingsGlobalKey = "global"
+
+// UnmarshalJSON decodes the user settings file with per-block strictness: the
+// `global` block is strict (an unknown key inside it is an error — an older
+// binary must fail closed rather than misread consent it does not understand),
+// while unknown top-level blocks are kept verbatim for round-tripping. See the
+// UserSettings type comment for why.
+func (us *UserSettings) UnmarshalJSON(data []byte) error {
+	var blocks map[string]json.RawMessage
+	if err := json.Unmarshal(data, &blocks); err != nil {
+		return fmt.Errorf("user settings: %w", err)
+	}
+	*us = UserSettings{}
+	for key, raw := range blocks {
+		if key != userSettingsGlobalKey {
+			if us.extra == nil {
+				us.extra = make(map[string]json.RawMessage, len(blocks))
+			}
+			us.extra[key] = raw
+			continue
+		}
+		if bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
+			continue
