+	setPolicyGlobal(t, `{"global":{"enabled":true},"future_feature":{"knob":1,"list":["a"]}}`)
+	settings, err := LoadUserSettings(t.Context())
+	if err != nil {
+		t.Fatalf("an unknown top-level block must not fail the load: %v", err)
