// applyUserOPFPreferences layers the user file's ordinary OPF keys
// (timeout_seconds, prompt_default) onto an OPF block the repository
// configured. It never creates the block: the user file says how OPF runs on
// this machine, not whether it runs — that is the team's call in
// .entire/settings.json. The command is deliberately not applied here; it is
// decided after the local merge by enforceOPFCommandTrust, where user wins.
func applyUserOPFPreferences(settings *EntireSettings, userOPF *repopolicy.UserOPFConfig) {
	if userOPF == nil || settings == nil || settings.Redaction == nil || settings.Redaction.OpenAIPrivacyFilter == nil {
		return
	}
	opf := settings.Redaction.OpenAIPrivacyFilter
	if userOPF.TimeoutSeconds > 0 {
		opf.TimeoutSeconds = userOPF.TimeoutSeconds
	}
	if userOPF.PromptDefault != "" {
		opf.PromptDefault = userOPF.PromptDefault
	}
}

